// The one place that reads Amp on a timer. It writes `orbs`, and the pane, tools and skyline read
// it. Module variables (timer, backoff) start over on a reload; the state itself is the host's.
// It takes a `Ports` instead of `$`: the engine follows `$` only inside the file that holds it.
import type { Orb, OrbPr } from '../types'
import { ampExport, ampList, ampUsage, ghPr } from './cli'
import { blankOrb, parseExport, parseUsage, shortTitles, sizeOfCores, STALE_MS, stateOf } from './model'
import type { Ports } from './ports'
import { EXPORT_GAP_MS, exportsDue, FAST_MS, GH_GAP_MS, listDelay, MAX_EXPORTS, QUIET_STOP_MS } from './scheduler'

const USAGE_GAP_MS = 60_000
const MAX_PR_CALLS = 8
const NOTIFY = ['-e', 'on run argv', '-e', 'display notification (item 1 of argv) with title (item 2 of argv)', '-e', 'end run']
// The store key of the notifications sent, `{ [event]: when }`, and how long an event is kept.
const NOTIFIED = 'notified'
const NOTIFIED_MS = 86_400_000
// A thread that still cannot be read this long after its change shows as failed, with this line.
const UNREADABLE_MS = 3_600_000
const UNREADABLE = 'cannot read this thread'

let timer: ReturnType<Ports['after']> | null = null
// When the pending timer fires. Only read while `timer` is set and still in the future.
let dueAt = 0
// The ports of the session's start: every timer runs on them, whichever dispatch asked for it. A
// timer armed on a tool call's or a press's ports belongs to that dispatch, and a cancelled
// dispatch drops it. Until a session start (or a measurement, after a reload) brings them, a
// caller's own ports stand in.
let session: Ports | null = null
// The cadence last in force, for the retry when a schedule's own read fails.
let cadence = FAST_MS
let failures = 0
let wantedUntil = 0
let lastPollAt = 0
let lastGhAt = 0
let polling: Promise<void> | null = null
// When an export last failed, per orb: a failing orb is retried at most every EXPORT_GAP_MS.
const failedExports = new Map<string, number>()
// When a message was last sent to an orb from here. Until a reading taken after it lands, the orb
// is working, whatever a read that started before the send says when it lands.
const sentAt = new Map<string, number>()
let notify = true
let notifyAfterMs = 300_000
// Notifications go out one at a time, so two in one pass never write over each other's key.
let notifying: Promise<void> = Promise.resolve()

export function configure(o: { notify: boolean; notifyAfterMs: number }): void {
  notify = o.notify
  notifyAfterMs = o.notifyAfterMs
}

export async function start(p: Ports): Promise<void> {
  session = p
  // A poll that throws must not end the watch: pollNow schedules the next read whatever happened.
  await pollNow(p).catch(() => undefined)
}

/**
 * From a frequent, short hook (the session's measurement after each turn): a reload cancels the
 * plugin's timers, and if no session start follows it, this arms the next read again. Idle, it
 * arms nothing.
 */
export async function rearm(p: Ports): Promise<void> {
  session ??= p
  await schedule(p)
}

/** Forget the timer and the backoff, as a reload does. For tests, which share this module. */
export function resetPoller(): void {
  timer?.cancel()
  timer = null
  dueAt = 0
  session = null
  cadence = FAST_MS
  failures = 0
  wantedUntil = 0
  lastPollAt = 0
  lastGhAt = 0
  polling = null
  failedExports.clear()
  sentAt.clear()
  notifying = Promise.resolve()
}

export async function want(p: Ports, forMs = 600_000): Promise<void> {
  wantedUntil = Math.max(wantedUntil, (await p.now()) + forMs)
  await schedule(p)
}

export async function pollNow(p: Ports, maxAgeMs = 0): Promise<void> {
  try {
    // A read already under way is the freshest there is: wait for it rather than answer from before it.
    if (polling) return await polling
    if ((await p.now()) - lastPollAt < maxAgeMs) return
    polling ??= pollOnce(p).finally(() => {
      polling = null
    })

    return await polling
  } finally {
    // Whoever asked, the next read is scheduled: a read after the idle stop may have found work.
    await schedule(p)
  }
}

/** A read that starts after this call: one already under way may predate what the caller just did, so it is waited out first. */
export async function pollFresh(p: Ports): Promise<void> {
  if (polling) await polling.catch(() => undefined)

  return pollNow(p)
}

export async function addStarted(p: Ports, orb: Orb): Promise<void> {
  await p.orbs.set(list => [orb, ...list.filter(o => o.id !== orb.id)])
}

/** A message reached the orb: it is working from now, so waits and labels see the new turn at once. */
export async function markSent(p: Ports, id: string): Promise<void> {
  sentAt.set(id, await p.now())
  await p.orbs.set(list => list.map(afterSend))
}

// The orb as a send from here leaves it: a change at the send's time that no reading has seen yet.
function afterSend(o: Orb): Orb {
  const at = sentAt.get(o.id)
  if (at === undefined || o.exportedAt >= at) return o

  return { ...o, state: 'working', changedAt: Math.max(o.changedAt, at), isEnded: false, isListOnly: false }
}

// A toast or a notification is news only for an orb whose thread was read, or that was started
// here: an orb seen for the first time, or never read since, may have ended its turn long ago.
const isKnown = (o: Orb) => o.exportedAt > 0 || o.isStartedHere

async function schedule(p: Ports): Promise<void> {
  const host = session ?? p
  try {
    // Every await comes first. From the cancel to the assignment there is none, so overlapping calls
    // (start, want, a timer firing) can never leave a second timer behind that nothing can cancel.
    const now = await host.now()
    const delay = listDelay(now, await host.orbs.get(), wantedUntil, failures)
    if (delay !== null) cadence = delay
    // A pending timer that fires no later than this one stays: re-arming a full delay on every call
    // would starve a caller that asks more often than the cadence (the pane, an orb_wait loop).
    if (delay !== null && timer && dueAt > now && dueAt <= now + delay) return
    timer?.cancel()
    timer = null
    if (delay === null) return
    arm(host, delay, now + delay)
  } catch {
    // A read that fails must not end the chain: unless a timer is pending, try again at the cadence
    // last in force. Its due time is unknown, so the next schedule that can read replaces it.
    try {
      if (!timer) arm(host, cadence, Infinity)
    } catch {
      // No clock at all: the next pollNow, want or measurement schedules again.
    }
  }
}

function arm(host: Ports, delay: number, at: number): void {
  dueAt = at
  const own = host.after(delay, () => {
    // Only its own: a callback that comes late must not forget the timer that replaced it.
    if (timer === own) timer = null
    void pollNow(session ?? host).catch(() => undefined)
  })
  timer = own
}

function mergePrs(old: readonly OrbPr[], found: readonly OrbPr[]): OrbPr[] {
  const byUrl = new Map(old.map(pr => [pr.url, pr]))

  return found.map(pr => byUrl.get(pr.url) ?? pr)
}

async function pollOnce(p: Ports): Promise<void> {
  const now = await p.now()
  lastPollAt = now
  let rows
  try {
    rows = await ampList(p)
  } catch (error) {
    failures += 1
    const text = error instanceof Error ? error.message : String(error)
    const old = await p.error.get()
    if (old?.text !== text) await p.error.set(() => ({ text, at: now }))

    return
  }
  failures = 0
  const before = await p.orbs.get()
  const byId = new Map(before.map(o => [o.id, o]))
  const changed = new Set<string>()
  const next: Orb[] = []
  for (const row of rows) {
    if (!row.isOrb) continue
    const old = byId.get(row.id)
    if (!old && now - row.updatedAt > STALE_MS) continue
    const isChanged = !old || old.updatedAt !== row.updatedAt || old.messageCount !== row.messageCount
    if (isChanged) changed.add(row.id)
    next.push(afterSend({
      ...(old ?? blankOrb(row.id)),
      title: row.title,
      updatedAt: row.updatedAt,
      messageCount: row.messageCount,
      changedAt: !isChanged ? old!.changedAt : old ? now : row.updatedAt,
      // Quiet for over an hour when first seen: not read until it changes or is selected.
      isListOnly: old ? old.isListOnly && !isChanged : now - row.updatedAt > QUIET_STOP_MS,
    }))
  }
  for (const old of before) {
    if (old.isStartedHere && !next.some(o => o.id === old.id) && now - old.changedAt < STALE_MS) next.push(afterSend(old))
  }
  const selected = await p.selected.get()
  const isPaneOpen = await p.isPaneOpen.get()
  // A few per pass: the rest keep their unread change and are read on a later pass.
  const due = exportsDue(now, next, changed, selected, isPaneOpen).filter(id => now - (failedExports.get(id) ?? -Infinity) >= EXPORT_GAP_MS)
  for (const id of due.slice(0, MAX_EXPORTS)) {
    const i = next.findIndex(o => o.id === id)
    const orb = next[i]!
    try {
      const view = parseExport(await ampExport(p, id))
      failedExports.delete(id)
      if ((sentAt.get(id) ?? Infinity) <= now) sentAt.delete(id)
      next[i] = { ...orb, mode: view.mode ?? orb.mode, createdAt: view.createdAt || orb.createdAt, steps: view.steps, prs: mergePrs(orb.prs, view.prs), finalText: view.finalText, agentState: view.agentState, isEnded: view.isEnded, isErrored: view.isErrored, exportedAt: now, isListOnly: false }
    } catch {
      // Keep the last good reading, and wait a full gap before trying this orb again.
      failedExports.set(id, now)
      // After an hour it stops spinning: failed, and read as of now until it changes again, so the
      // reads wind down. Quietly (its turn counts as seen): orbit cannot read it, which is no news of the orb.
      if (!orb.isListOnly && now - orb.changedAt >= UNREADABLE_MS) {
        next[i] = { ...orb, isErrored: true, finalText: UNREADABLE, exportedAt: now, seenTurn: `${id}:${orb.messageCount}` }
      }
    }
  }
  for (let i = 0; i < next.length; i += 1) next[i] = { ...next[i]!, state: stateOf(next[i]!, now) }
  // Only an orb read before can end a turn: a first read (a session's staggered start-up) is no news.
  const isTurnEnd = next.some(o => {
    const old = byId.get(o.id)

    return !!old && isKnown(old) && old.state === 'working' && o.state !== 'working'
  })
  if (isPaneOpen || isTurnEnd) await refreshPrs(p, next, now, isTurnEnd)
  if (isPaneOpen && selected) await refreshUsage(p, next, selected, now)
  announce(p, before, next, now)
  // The exports and gh calls above took minutes at worst, and an orb may have been added meanwhile
  // (orb_start's addStarted): keep what appeared since `before`, and apply the same rule to whatever
  // the cell holds at write time, so a set that lands between this read and the write is not lost.
  // A message sent while this read was under way started a turn this read cannot have seen.
  const known = new Set([...before, ...next].map(o => o.id))
  const withAdded = (current: Orb[]): Orb[] => [...current.filter(o => !known.has(o.id)), ...next.map(afterSend)]
  const current = await p.orbs.get()
  if (JSON.stringify(current) !== JSON.stringify(withAdded(current))) await p.orbs.set(withAdded)
  if ((await p.error.get()) !== null) await p.error.set(() => null)
}

async function refreshPrs(p: Ports, orbs: Orb[], now: number, isForced: boolean): Promise<void> {
  if (!isForced && now - lastGhAt < GH_GAP_MS) return
  lastGhAt = now
  let calls = 0
  for (let i = 0; i < orbs.length; i += 1) {
    const orb = orbs[i]!
    if (orb.state === 'stale' || orb.prs.length === 0) continue
    const prs = [...orb.prs]
    for (let j = 0; j < prs.length && calls < MAX_PR_CALLS; j += 1) {
      if (prs[j]!.state === 'merged' || prs[j]!.state === 'closed') continue
      calls += 1
      try {
        prs[j] = { ...prs[j]!, ...(await ghPr(p, prs[j]!.url)) }
      } catch {
        // gh missing or offline: badges stay as they were.
      }
    }
    orbs[i] = { ...orb, prs }
  }
}

async function refreshUsage(p: Ports, orbs: Orb[], id: string, now: number): Promise<void> {
  const old = await p.usage.get()
  if (old?.id === id && now - old.fetchedAt < USAGE_GAP_MS) return
  try {
    const u = parseUsage(await ampUsage(p, id))
    await p.usage.set(() => ({ id, ...u, fetchedAt: now }))
    const i = orbs.findIndex(o => o.id === id)
    const size = sizeOfCores(u.cores)
    if (i >= 0 && size && !orbs[i]!.size) orbs[i] = { ...orbs[i]!, size }
  } catch {
    // Usage is optional detail.
  }
}

function announce(p: Ports, before: readonly Orb[], next: Orb[], now: number): void {
  const prev = new Map(before.map(o => [o.id, o]))
  const shorts = shortTitles(next.map(o => o.title))
  next.forEach((orb, i) => {
    const old = prev.get(orb.id)
    if (!old || !isKnown(old)) return
    const name = shorts[i] ?? orb.title
    for (const pr of orb.prs) {
      if (!old.prs.some(q => q.url === pr.url)) {
        p.toast(`◉ ${name} opened PR #${pr.number}`)
        ping(p, orb, `opened PR #${pr.number}`, `${orb.id}:${pr.url}`, now)
      }
    }
    const turn = `${orb.id}:${orb.messageCount}`
    if (old.state !== 'working' || orb.state === 'working' || orb.seenTurn === turn) return
    next[i] = { ...orb, seenTurn: turn }
    if (orb.state === 'failed') {
      p.toast(`◉ ${name} failed`)
      ping(p, orb, 'failed', turn, now)
    } else if (orb.state === 'waiting') {
      p.toast(`◉ ${name} is waiting on you`)
    } else if (orb.state === 'done') {
      p.toast(`◉ ${name} finished`)
    }
  })
}

function ping(p: Ports, orb: Orb, what: string, key: string, now: number): void {
  if (!notify || !orb.createdAt || now - orb.createdAt < notifyAfterMs) return
  const title = Array.from(orb.title.replace(/[\u0000-\u001f\u007f]/g, ' ')).slice(0, 120).join('')
  notifying = notifying.then(() => notifyOnce(p, key, `${title} ${what}`, now)).catch(() => undefined)
}

// A macOS notification is system-wide, and every open session polls on its own and sees the same
// event: the store, which the sessions share, remembers each event notified (`key`, for a day), so
// it is sent once. A toast stays per session, since it shows in that session's window.
async function notifyOnce(p: Ports, key: string, text: string, now: number): Promise<void> {
  try {
    const raw = await p.store.get(NOTIFIED)
    const seen: Record<string, number> = {}
    if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
      for (const [k, at] of Object.entries(raw)) if (typeof at === 'number' && now - at < NOTIFIED_MS) seen[k] = at
    }
    if (key in seen) return
    seen[key] = now
    await p.store.set(NOTIFIED, seen)
  } catch {
    // The store cannot be read or written: notify anyway, at worst once per session.
  }
  await p.run(['osascript', ...NOTIFY, '--', text, 'orbit'], { timeoutMs: 10_000 })
}

files.hooks/ports.ts:
// Every way orbit's modules reach the engine. The engine follows `$` only inside the file that
// holds it, so register.tsx builds these closures from literal `$.noun.event(...)` calls, and the
// other modules take a Ports instead of `$`.
import type { Orb, OrbitError, OrbUsage } from '../types'
import type { Host } from './cli'

export const PANE = 'orbit'

export type Cell<T> = { get: () => Promise<T>; set: (change: (value: T) => T) => Promise<T> }

export type Ports = Host & {
  now: () => Promise<number>
  after: (ms: number, fn: () => void) => { cancel: () => void }
  toast: (text: string) => void
  openPane: () => Promise<unknown>
  checkTool: (tool: string, input: Record<string, unknown>) => Promise<{ decision: 'allow' | 'ask' | 'deny'; reason?: string }>
  // The plugin's own store: kept on disk and shared by every session of the user.
  store: { get: (key: string) => Promise<unknown>; set: (key: string, value: unknown) => Promise<void> }
  orbs: Cell<Orb[]>
  selected: Cell<string | null>
  usage: Cell<OrbUsage | null>
  error: Cell<OrbitError | null>
  armed: Cell<string | null>
  isPaneOpen: Cell<boolean>
}

files.hooks/sphere.ts:
// An orb drawn the way Amp draws its own: a dark globe with thin latitude and meridian lines in
// the thread's colour. The meridians turn and the status ring's gap travels only while the orb
// works. The animation is SMIL inside the SVG, so no timer in the mod ever ticks for it. Ring
// colours are Claude Code's theme values (an SVG cannot read the theme), with a light-mode swap.
import type { OrbSize, OrbState } from '../types'

export const RING: Record<OrbState, { dark: string; light: string }> = {
  working: { dark: '#D97757', light: '#C6613F' },
  waiting: { dark: '#B1B9F9', light: '#5769F7' },
  done: { dark: '#4EBA65', light: '#2C7A39' },
  failed: { dark: '#FF6B80', light: '#AB2B3F' },
  stale: { dark: '#999999', light: '#666666' },
}

export const STATE_KEY: Record<OrbState, string> = { working: 'claude', waiting: 'suggestion', done: 'success', failed: 'error', stale: 'inactive' }

export function radiusOf(size: OrbSize | null): number {
  return size === 'a1.small' ? 28 : size === 'a1.large' ? 40 : 34
}

const f = (n: number) => Number(n.toFixed(1))

export function sphereSvg(o: { tint: string; state: OrbState; radius: number; isSelected: boolean }): string {
  const r = o.radius
  const pad = 6
  const size = (r + pad) * 2
  const c = size / 2
  const ring = RING[o.state]
  const isSpinning = o.state === 'working'
  const ringR = r + 3
  const around = f(2 * Math.PI * ringR)
  // At rest the two meridians stand at different turns, so a still globe shows both.
  const meridian = (begin: string, rx: number) =>
    `<ellipse cx="${c}" cy="${c}" rx="${f(r * rx)}" ry="${r}">${
      isSpinning ? `<animate attributeName="rx" values="${f(r * 0.95)};${f(r * 0.05)};${f(r * 0.95)}" dur="4s" begin="${begin}" repeatCount="indefinite" calcMode="spline" keySplines=".42 0 .58 1;.42 0 .58 1"/>` : ''
    }</ellipse>`

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">` +
    `<style>.ring{stroke:${ring.dark}}@media (prefers-color-scheme: light){.ring{stroke:${ring.light}}}</style>` +
    `<defs><radialGradient id="b" cx="42%" cy="38%" r="65%"><stop offset="0" stop-color="#2b3a3c"/><stop offset="1" stop-color="#0c1516"/></radialGradient>` +
    `<clipPath id="k"><circle cx="${c}" cy="${c}" r="${r}"/></clipPath></defs>` +
    `<circle cx="${c}" cy="${c}" r="${r}" fill="url(#b)"/>` +
    `<g clip-path="url(#k)" fill="none" stroke="${o.tint}" stroke-width="1" stroke-opacity="0.55">` +
    `<ellipse cx="${c}" cy="${c}" rx="${r}" ry="${f(r * 0.28)}"/>` +
    `<ellipse cx="${c}" cy="${f(c - r * 0.5)}" rx="${f(r * 0.87)}" ry="${f(r * 0.16)}"/>` +
    `<ellipse cx="${c}" cy="${f(c + r * 0.5)}" rx="${f(r * 0.87)}" ry="${f(r * 0.16)}"/>` +
    meridian('0s', 0.45) +
    meridian('-2s', 0.85) +
    `</g>` +
    `<circle class="ring" cx="${c}" cy="${c}" r="${ringR}" fill="none" stroke-width="${o.isSelected ? 2.5 : 1.5}" stroke-linecap="round"${
      isSpinning ? ` stroke-dasharray="${f(around * 0.84)} ${f(around * 0.16)}"` : ''
    }>${isSpinning ? `<animateTransform attributeName="transform" type="rotate" from="0 ${c} ${c}" to="360 ${c} ${c}" dur="2.4s" repeatCount="indefinite"/>` : ''}</circle>` +
    `</svg>`
  )
}

const STROKE = 1.5

// Inset by the stroke width, so the peak, the floor and the ends are drawn whole. One sample is a flat line.
export function sparkSvg(values: readonly number[], width: number, height: number, color: string): string {
  const series = values.length === 1 ? [values[0]!, values[0]!] : values
  const max = Math.max(1, ...series)
  const step = series.length > 1 ? (width - 2 * STROKE) / (series.length - 1) : 0
  const points = series.map((v, i) => `${f(STROKE + i * step)},${f(height - STROKE - (v / max) * (height - 2 * STROKE))}`).join(' ')

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">${
    series.length ? `<polyline fill="none" stroke="${color}" stroke-width="${STROKE}" stroke-linejoin="round" points="${points}"/>` : ''
  }</svg>`
}

const BARS = '▁▂▃▄▅▆▇█'

/** The terminal's sparkline: the last twelve samples as bars, scaled to their peak. */
export function sparkText(values: readonly number[]): string {
  const last = values.slice(-12)
  const max = Math.max(1, ...last)

  return last.map(v => BARS[Math.round((Math.max(0, v) / max) * 7)]).join('')
}

// SMIL elements, self-closing or with children (an animateMotion's mpath).
const SMIL = /<(animate(?:Transform|Motion)?)\b[^>]*?(?:\/>|>[\s\S]*?<\/\1\s*>)/g

/** The same drawing without its animation: a finished step's icon stands still. */
export function stillSvg(svg: string): string {
  return svg.replace(SMIL, '')
}

files.hooks/tools.ts:
// Claude's native orb tools. They share the poller's cache. Waits sleep in a host `sleep` process,
// because a `$.clock.sleep` would count against the hook's own time budget.
// It takes a `Ports` instead of `$`: the engine follows `$` only inside the file that holds it, so
// register.tsx serves these with `serveTool(portsOf($), e, next.signal)`.
import type { Orb } from '../types'
import { pressArchive, sendMessage } from './actions'
import { ampExport, ampStart, isThreadId, StartUnsure } from './cli'
import { blankOrb, MARK, parseExport, shortTitles } from './model'
import { addStarted, pollNow, want } from './poller'
import type { Ports } from './ports'
import { WATCH_MS } from './scheduler'

const MODES = ['low', 'medium', 'high', 'ultra']
const SIZES = ['a1.small', 'a1.medium', 'a1.large']
const UNTIL = ['idle', 'pr', 'any']
// A wait's step is one tiny `sleep` process, short enough that a cancelled call is noticed inside
// the engine's linger. The poller owns every Amp read: a wait only asks it to keep its watched
// cadence going (`want`), so waiting adds no reads of its own.
const WAIT_STEP_MS = 5_000
const WAIT_DEFAULT_MIN = 30
const WAIT_MAX_MIN = 120
// A read this fresh answers a status call or an archive without another one.
const FRESH_MS = 15_000
// orb_status lists, by default, the orbs that are active or changed this recently.
const RECENT_MS = 3_600_000
// The most of a stopped orb's last message orb_status shows, and of a report orb_result returns.
const TAIL = 160
const RESULT_MAX = 3_000
const MAX_PRS = 3
// Plugin tools answered in a hook never reach the engine's permission prompt, so these three, which
// change something, run only on an explicit allow. The read-only tools stop only on an explicit deny.
const GATED = ['orb_start', 'orb_send', 'orb_archive']

type ToolSpec = { name: string; description: string; inputSchema: Record<string, unknown> }
type Served = { result: string } | { deny: string }

// What Claude reads on every turn of every session, so each word earns its place.
const STR = { type: 'string' }
const IDS = { type: 'array' }
const object = (properties: Record<string, unknown>, ...required: string[]) => ({ type: 'object', properties, ...(required.length ? { required } : {}) })
const ONE = object({ id: STR }, 'id')

export const TOOLS: ToolSpec[] = [
  { name: 'orb_start', description: 'Start an Amp orb on project owner/name. Defaults: mode ultra, size a1.small. Put the whole task in prompt.', inputSchema: object({ title: STR, prompt: STR, project: STR, mode: { enum: MODES }, size: { enum: SIZES } }, 'title', 'prompt', 'project') },
  { name: 'orb_send', description: 'Message an orb.', inputSchema: object({ id: STR, message: STR }, 'id', 'message') },
  { name: 'orb_status', description: 'Orbs active or changed in the last hour; all: every orb. URL ampcode.com/threads/<id>', inputSchema: object({ ids: IDS, all: { type: 'boolean' } }) },
  { name: 'orb_wait', description: `Wait until orbs are idle (default), each has a new pr, or any ends a turn or opens a PR. Default ${WAIT_DEFAULT_MIN} min, max ${WAIT_MAX_MIN}.`, inputSchema: object({ ids: IDS, until: { enum: UNTIL }, timeoutMinutes: { type: 'number' } }, 'ids') },
  { name: 'orb_result', description: "An orb's final message.", inputSchema: ONE },
  { name: 'orb_archive', description: 'Archive an orb.', inputSchema: ONE },
]

const str = (v: unknown) => (typeof v === 'string' ? v.trim() : '')
const list = (v: unknown) => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : [])
const reason = (error: unknown) => (error instanceof Error ? error.message : String(error))

// One line per orb: the id (the other tools need it), what it is doing or how it ended, its PRs.
function lineOf(o: Orb, title: string): string {
  const step = o.state === 'working' ? o.steps[o.steps.length - 1] : undefined
  // Marks only for a PR gh has checked: one never checked (state unknown) is its number alone.
  const prs = o.prs.slice(0, MAX_PRS).map(pr => (pr.state === 'unknown' ? `#${pr.number}` : pr.state === 'open' ? `#${pr.number} CI${MARK[pr.ci]} CR${MARK[pr.review]}` : `#${pr.number} ${pr.state}`))
  const flat = o.state === 'working' ? '' : o.finalText.replace(/\s+/g, ' ').trim()

  return [
    `${o.id} ${title.replace(/\s+/g, ' ').trim()}`,
    o.state,
    [o.mode, o.size?.replace('a1.', '')].filter(Boolean).join('/'),
    step ? `${step.verb} ${step.target}`.trim() : '',
    prs.length ? `PR ${prs.join(', ')}${o.prs.length > MAX_PRS ? ` +${o.prs.length - MAX_PRS}` : ''}` : '',
    flat ? `"${flat.length > TAIL ? `…${flat.slice(1 - TAIL).trimStart()}` : flat}"` : '',
  ].filter(Boolean).join(' · ')
}

async function statusText(p: Ports, o: { ids?: readonly string[]; all?: boolean } = {}): Promise<string> {
  const now = await p.now()
  const orbs = await p.orbs.get()
  const titles = shortTitles(orbs.map(x => x.title))
  const isShown = (x: Orb) => (o.ids?.length ? o.ids.includes(x.id) : o.all || ['working', 'waiting', 'failed'].includes(x.state) || now - x.changedAt < RECENT_MS)
  const lines = orbs.flatMap((x, i) => (isShown(x) ? [lineOf(x, titles[i] ?? x.title)] : []))
  const error = await p.error.get()
  if (error) lines.unshift(`amp failing: ${error.text}`)

  return lines.join('\n') || (orbs.length ? `no orbs to show (${orbs.length} tracked; all: true lists them)` : 'no orbs tracked')
}

// `seenWorking` holds every orb seen working since the wait began, so `any` also catches a turn
// that started during the wait (a message sent from the pane, or by Claude just before).
type Baseline = { prs: Map<string, number>; seenWorking: Set<string> }

function isMet(until: string, orbs: readonly Orb[], wanted: readonly string[], before: Baseline): boolean {
  const mine = wanted.map(id => orbs.find(o => o.id === id))
  const hasNewPr = (o: Orb) => o.prs.length > (before.prs.get(o.id) ?? 0)
  if (until === 'pr') return mine.every(o => !!o && hasNewPr(o))
  if (until === 'any') return mine.some(o => !!o && (hasNewPr(o) || (before.seenWorking.has(o.id) && o.state !== 'working')))

  return mine.every(o => !!o && o.state !== 'working')
}

async function denial(p: Ports, e: Record<string, unknown>, tool: string): Promise<string | null> {
  const input = Object.fromEntries(Object.entries(e).filter(([key]) => key !== 'tool' && key !== 'tool_use_id'))
  const rule = `Add mcp__orbit__${tool} (or mcp__orbit__*) to your allow rules.`
  let decision: string
  try {
    const check = await p.checkTool(String(e.tool), input)
    if (check.decision === 'deny') return `orbit: ${check.reason ?? 'denied by permission settings'}`
    decision = check.decision
  } catch (error) {
    // A check that cannot answer does not stop a read-only tool, and never lets a gated one through.
    return GATED.includes(tool) ? `orbit: ${tool} was not run, its permission check failed (${reason(error)}). ${rule}` : null
  }

  return GATED.includes(tool) && decision !== 'allow' ? `orbit: ${tool} needs permission. ${rule}` : null
}

// Every read in one hook run sees one moment, however long the run lasts, and only a write of the
// run's own moves it on (`$.state.get`). A wait sleeps between reads, so it would never see what the
// poller's timer found meanwhile. Writing the list back unchanged hands back the list as it stands now.
const current = (p: Ports) => p.orbs.set(list => list)

// Resolves when the call is cancelled. A signal that cannot be listened to is still checked by
// `aborted` at every step, so a cancel is then noticed at the next one.
function onAbort(signal: AbortSignal): { aborted: Promise<void>; off: () => void } {
  let off = () => {}
  const aborted = new Promise<void>(resolve => {
    if (signal.aborted) return resolve()
    if (typeof signal.addEventListener !== 'function') return
    const listener = () => resolve()
    signal.addEventListener('abort', listener, { once: true })
    off = () => signal.removeEventListener?.('abort', listener)
  })

  return { aborted, off: () => off() }
}

async function wait(p: Ports, e: Record<string, unknown>, signal: AbortSignal): Promise<Served> {
  const given = list(e.ids)
  const wanted = given.filter(isThreadId)
  if (wanted.length === 0 || wanted.length < given.length) return { deny: 'orb_wait: ids must list Amp thread ids like T-01a1…' }
  const until = e.until === undefined ? 'idle' : str(e.until)
  if (!UNTIL.includes(until)) return { deny: `orb_wait: until must be one of ${UNTIL.join(', ')}` }
  const minutes = Math.min(WAIT_MAX_MIN, Math.max(1, Number(e.timeoutMinutes ?? WAIT_DEFAULT_MIN) || WAIT_DEFAULT_MIN))
  const deadline = (await p.now()) + minutes * 60_000
  // The baseline is what was known before this wait read Amp, so a PR the first read finds counts as new.
  const first = await p.orbs.get()
  const before: Baseline = { prs: new Map(first.map(o => [o.id, o.prs.length])), seenWorking: new Set(first.filter(o => o.state === 'working').map(o => o.id)) }
  const stopped = async (why: string) => ({ result: `${why}\n${await statusText(p, { ids: wanted })}` })
  const cancel = onAbort(signal)
  try {
    // The one read the wait asks for, and only when the cache is older than the watched cadence.
    if (!signal.aborted) await pollNow(p, WATCH_MS)
    for (;;) {
      if (signal.aborted) return await stopped('stopped waiting.')
      // Keeps the poller's 30 second cadence alive; it lapses about a minute after the wait ends.
      await want(p, 2 * WATCH_MS)
      const orbs = await current(p)
      if (isMet(until, orbs, wanted, before)) return { result: await statusText(p, { ids: wanted }) }
      for (const o of orbs) if (o.state === 'working') before.seenWorking.add(o.id)
      // The read that just landed either failed or listed what Amp has: say so now, not at the timeout.
      const error = await p.error.get()
      // The status below leads with the error itself.
      if (error) return await stopped('stopped waiting: Amp could not be read.')
      const missing = wanted.filter(id => !orbs.some(o => o.id === id))
      if (until === 'any' ? missing.length === wanted.length : missing.length > 0) {
        return await stopped(`stopped waiting: ${missing.join(', ')} ${missing.length === 1 ? 'is' : 'are'} not tracked (not in Amp's recent orbs, or archived).`)
      }
      const now = await p.now()
      if (now >= deadline) return await stopped(`timed out after ${minutes} min.`)
      if (signal.aborted) return await stopped('stopped waiting.')
      // The last step is cut to the time left, so a wait does not overrun its deadline.
      const stepMs = Math.min(WAIT_STEP_MS, deadline - now)
      const slept = p
        .run(['sleep', String(stepMs / 1000)], { timeoutMs: stepMs + 10_000 })
        .then(out => (out.exitCode === 0 ? null : `sleep exited ${out.exitCode}`), error => reason(error))
      // A cancel ends the step at once; the `sleep` process is left to finish by itself.
      const outcome = await Promise.race([slept, cancel.aborted.then(() => 'cancelled' as const)])
      // Without a working sleep this would spin until the deadline: say so and stop instead.
      if (outcome !== null && outcome !== 'cancelled') return await stopped(`stopped waiting: ${outcome}.`)
    }
  } finally {
    cancel.off()
  }
}

export async function serveTool(p: Ports, e: Record<string, unknown>, signal: AbortSignal): Promise<Served> {
  const tool = String(e.tool).replace('mcp__orbit__', '')
  const denied = await denial(p, e, tool)
  if (denied) return { deny: denied }

  if (tool === 'orb_start') {
    const title = str(e.title)
    const prompt = str(e.prompt)
    const project = str(e.project)
    const mode = str(e.mode) || 'ultra'
    const size = str(e.size) || 'a1.small'
    if (!title || !prompt || !project) return { deny: 'orb_start: title, prompt and project are required' }
    if (!MODES.includes(mode)) return { deny: `orb_start: mode must be one of ${MODES.join(', ')}` }
    if (!SIZES.includes(size)) return { deny: `orb_start: size must be one of ${SIZES.join(', ')}` }
    let started
    try {
      started = await ampStart(p, { title, prompt, project, mode, size })
    } catch (error) {
      if (!(error instanceof StartUnsure)) throw error
      // amp ran, so an orb may be up: say so, rather than a plain error that invites a second one.
      await want(p)
      const seen = error.urls.length > 0 ? ` amp printed: ${error.urls.join(' ')}` : ''

      return { result: `orb_start: the orb may have started; check orb_status before retrying (${error.message}).${seen}` }
    }
    const now = await p.now()
    await addStarted(p, { ...blankOrb(started.id), title, mode, size: size as Orb['size'], createdAt: now, updatedAt: now, changedAt: now, isStartedHere: true })
    await want(p)

    return { result: `Started ${started.id} (${mode}, ${size}): ${started.url}. orbit is watching it; use orb_wait to wait for it.` }
  }

  if (tool === 'orb_send' || tool === 'orb_result' || tool === 'orb_archive') {
    const id = str(e.id)
    if (!isThreadId(id)) return { deny: `${tool}: id must be an Amp thread id like T-01a1…` }
    if (tool === 'orb_send') {
      const message = str(e.message)
      if (!message) return { deny: 'orb_send: message is empty' }
      const sent = await sendMessage(p, id, message)

      return sent === 'sent' ? { result: `sent to ${id}` } : { deny: `orb_send: ${sent} to ${id}` }
    }
    if (tool === 'orb_result') {
      const view = parseExport(await ampExport(p, id))
      if (!view.finalText) return { result: '(no final message yet)' }
      const text = view.finalText.length > RESULT_MAX ? `(the last ${RESULT_MAX} characters; the whole report is in the thread)\n${view.finalText.slice(-RESULT_MAX)}` : view.finalText

      // Mid-turn text is not a report: say so rather than hand it over as one.
      return { result: view.isEnded ? text : `(still working, latest message so far)\n${text}` }
    }
    // A tool call is already an explicit decision, so this presses archive until it has gone through
    // (the pane asks twice; an orb the pane had already armed needs only one press).
    if ((await pressArchive(p, id)) === 'armed') await pressArchive(p, id)
    // A read that started before the archive may still list the orb and write it back when it ends:
    // wait that read out (or read, if the last one is stale), then take the orb off the list again.
    await pollNow(p, FRESH_MS)
    await p.orbs.set(orbs => orbs.filter(o => o.id !== id))

    return { result: `archived ${id}` }
  }

  if (tool === 'orb_status') {
    await pollNow(p, FRESH_MS)

    return { result: await statusText(p, { ids: list(e.ids), all: e.all === true }) }
  }

  if (tool === 'orb_wait') return wait(p, e, signal)

  return { deny: `orbit: unknown tool ${tool}` }
}

